860|        }
861|    }
862|
863|    result = parse_value(lex, flags, error);
864|    if (!result)
865|        return NULL;
866|
867|    if (!(flags & JSON_DISABLE_EOF_CHECK)) {
868|        lex_scan(lex, error);
